import re

import database

# =====================================================
# STATIC, REFERENCE-ONLY SECURITY FACTS
# =====================================================
# CWE-89/CWE-295 are official, stable MITRE Common Weakness Enumeration
# definitions - not app-specific claims, not generated by any model, and
# not something that varies per request. Safe to state as fixed text,
# the same way predictor.py's CWE_BY_TYPE mapping already treats them as
# fixed reference data. These never mention a specific app.

CWE_89_EXPLANATION = (
    "CWE-89 is SQL Injection. It happens when untrusted input (e.g. user "
    "input, an Intent extra, a URL parameter) is concatenated directly "
    "into a SQL query string instead of being passed as a separate, "
    "parameterized argument. An attacker who controls that input can "
    "change the query's meaning - reading, modifying, or deleting data "
    "the app never intended to expose.\n\n"
    "The standard fix is to use parameterized queries (e.g. "
    "db.rawQuery(sql, selectionArgs) with '?' placeholders) so user input "
    "is always treated as data, never as part of the SQL syntax itself."
)

CWE_295_EXPLANATION = (
    "CWE-295 is Improper Certificate Validation. It happens when an app's "
    "TLS/SSL certificate or hostname checking is weakened or bypassed - "
    "for example a HostnameVerifier.verify() that always returns true, "
    "or a TrustManager.checkServerTrusted() with an empty body. That lets "
    "an attacker on the network (e.g. a malicious Wi-Fi hotspot) "
    "intercept or tamper with traffic the app believes is secure "
    "(a man-in-the-middle attack).\n\n"
    "The standard fix is to let certificate/hostname validation run its "
    "real, default checks rather than overriding them to always succeed."
)

RECOMMENDATION_EXPLANATIONS = {
    "AVOID_INSTALLING": "AVOID INSTALLING means the most recent scan found high-risk security issues serious enough that installing this app is not recommended.",
    "INSTALL_WITH_CAUTION": "INSTALL WITH CAUTION means some potential security risks were found, but they weren't severe enough to recommend avoiding the app outright - review the findings before deciding.",
    "SAFE_TO_INSTALL": "SAFE TO INSTALL means the most recent scan did not find a security vulnerability in this app.",
    "MANUAL_REVIEW": "MANUAL REVIEW means the evidence was mixed or inconclusive, so this needs a human look rather than an automatic verdict.",
}

GREETING = (
    "Hello! I am the DualVulnDroid Security Bot 🤖. You can ask me things like "
    "'Is TikTok safe?', 'What is CWE-89?', or open this chat from an app's "
    "details screen and ask 'Why is this app risky?'."
)


def analyze_user_query(app_name: str, user_ram_mb: int = 2048, user_android_version: int = 10):
    """
    Looks up the app's most recent REAL assessment (from an actual
    /upload-apk scan). If the app has never been scanned, this says so
    explicitly instead of guessing a risk level or score.

    Device compatibility (RAM/Android version) is intentionally not
    evaluated here: this project has no reliable source for an app's
    minimum RAM requirement, so rather than fabricate thresholds we don't
    report a RAM-based compatibility verdict for chat-only lookups.
    Android-version compatibility IS available when a real minSdkVersion
    was extracted from the APK - see answer_compatibility_question().
    """
    assessment = database.get_app_assessment(app_name)

    if assessment is None:
        return {
            "app_name": app_name,
            "risk_level": "unknown",
            "security_score": None,
            "is_compatible": True,
            "compatibility_issues": [],
            "recommendation": (
                f"No security assessment available yet for '{app_name}'. "
                "Upload its APK to get a real analysis."
            ),
            "alternatives": [],
            "details": [],
            "assessed": False
        }

    risk_level = assessment["risk_level"]
    score = assessment["security_score"]

    if risk_level == "high":
        recommendation = "AVOID INSTALLING. The most recent analysed version has significant security findings."
    elif risk_level == "medium":
        recommendation = "INSTALL WITH CAUTION. Some potential risks were found in the most recent analysed version."
    else:
        recommendation = "No detected vulnerability in the most recently analysed version."

    alternatives = database.get_alternatives(assessment["category"], app_name)

    return {
        "app_name": app_name,
        "risk_level": risk_level,
        "security_score": score,
        "is_compatible": True,
        "compatibility_issues": [],
        "recommendation": recommendation,
        "alternatives": alternatives,
        "details": assessment["vulnerability_types"],
        "assessed": True,
        "scan_count": assessment["scan_count"],
        "last_scanned_at": assessment["last_scanned_at"],
    }


# =====================================================
# INTENT CLASSIFICATION (deterministic keyword matching -
# same style as the existing app-name regex, not an LLM)
# =====================================================

def _matches_any(text: str, phrases) -> bool:
    return any(p in text for p in phrases)


def _classify_intent(message: str) -> str:
    m = message.lower()

    if "cwe-89" in m or "cwe 89" in m or ("sql injection" in m and _matches_any(m, ["what is", "what's", "explain", "mean"])):
        return "explain_cwe_89"
    if "cwe-295" in m or "cwe 295" in m or ("certificate" in m and _matches_any(m, ["what is", "what's", "explain", "mean"])) \
            or ("certificate validation" in m):
        return "explain_cwe_295"
    if _matches_any(m, ["compatible", "compatibility"]):
        return "compatibility"
    if _matches_any(m, ["what does this recommendation mean", "what does the recommendation mean", "recommendation mean"]):
        return "explain_recommendation"
    if _matches_any(m, [
        "why is this app risky", "why risky", "why is it risky", "what security issues",
        "what were the findings", "what issues",
        # Phase 14B: found via real device testing - the Flutter client's
        # own built-in suggestion chip reads "Why is this app high risk?",
        # which didn't match any of the phrases above and silently fell
        # back to the generic greeting instead of a real, grounded answer.
        "high risk", "why is this app dangerous", "why dangerous",
    ]):
        return "why_risky"
    if _matches_any(m, ["what should i do", "how can this be fixed", "how do i fix", "how can i fix", "how to fix"]):
        return "what_to_do"
    return "app_lookup"  # existing behavior: try to extract an app name from free text


def _extract_app_name(message: str):
    msg_lower = message.lower()
    clean_msg = msg_lower.replace("?", "").replace("'", "").strip()
    words = clean_msg.split()

    if len(words) == 1:
        return words[0]

    match_is = re.search(r"is\s+(.*?)\s+safe", clean_msg)
    match_check = re.search(r"check\s+(.*)", clean_msg)
    if match_is:
        return match_is.group(1).strip()
    if match_check:
        return match_check.group(1).strip()
    return None


def _strip_legacy_context_prefix(message: str) -> str:
    """The Flutter client used to prepend a free-text sentence like
    'Regarding the application "X" (pkg), assessed risk level HIGH: '
    before the real question - this recovers just the user's question
    from that shape for intent classification, for backward
    compatibility with any client still doing that instead of sending
    the structured app_id field."""
    match = re.search(r":\s*(.+)$", message) if message.lower().startswith("regarding the application") else None
    return match.group(1).strip() if match else message


def _format_findings(vulnerability_types) -> str:
    return ", ".join(vulnerability_types) if vulnerability_types else "no specific finding types were recorded"


def answer_why_risky(assessment: dict) -> str:
    """assessment is a real, non-None dict from
    database.get_app_assessment_by_id() - its mere existence means the app
    has a completed scan (Scan.risk_level is stored lowercase by the real
    apk_scanner flow, so compare case-insensitively, the same convention
    alternatives.py/compatibility.py already use)."""
    risk_level = (assessment["risk_level"] or "").upper()
    if risk_level not in ("HIGH", "MEDIUM"):
        return f"'{assessment['app_name']}' isn't currently flagged as risky - no detected vulnerability in the most recently analysed version."
    reason = assessment.get("recommendation_reason")
    findings = _format_findings(assessment["vulnerability_types"])
    text = f"'{assessment['app_name']}' is flagged {risk_level} risk. Findings: {findings}."
    if reason:
        text += f"\n\n{reason}"
    return text


def answer_what_to_do(assessment: dict) -> str:
    decision = assessment.get("recommendation_decision")
    explanation = RECOMMENDATION_EXPLANATIONS.get(decision)
    if explanation:
        return explanation
    risk_level = (assessment["risk_level"] or "").upper()
    if risk_level == "HIGH":
        return "AVOID INSTALLING. The most recent analysed version has significant security findings."
    if risk_level == "MEDIUM":
        return "INSTALL WITH CAUTION. Some potential risks were found - review the findings before deciding."
    return "No detected vulnerability in the most recently analysed version - no specific action is needed."


def answer_recommendation_explanation(assessment: dict) -> str:
    decision = assessment.get("recommendation_decision")
    if decision and decision in RECOMMENDATION_EXPLANATIONS:
        return RECOMMENDATION_EXPLANATIONS[decision]
    return answer_what_to_do(assessment)


def answer_compatibility_question(assessment: dict, user_android_version: int) -> str:
    min_sdk = assessment.get("min_sdk_version")
    if min_sdk is None:
        return (
            f"The minimum Android version (API level) required by '{assessment['app_name']}' "
            "wasn't available from its manifest, so I can't give a compatibility verdict."
        )
    if user_android_version is None:
        return f"'{assessment['app_name']}' requires at least Android API level {min_sdk}. I don't know your device's Android version to compare against it."
    if user_android_version >= min_sdk:
        return f"Yes - '{assessment['app_name']}' requires Android API level {min_sdk} or higher, and your device reports API level {user_android_version}, so it meets the minimum Android version requirement."
    return f"No - '{assessment['app_name']}' requires Android API level {min_sdk} or higher, but your device reports API level {user_android_version}, which is below that."


def generate_chat_response(msg: str, user_ram_mb: int = 2048, user_android_version: int = 10, app_id: int = None):
    """
    Classifies the user's real question, then answers it from REAL stored
    data (when an app_id is given) or static, standard CWE reference text
    (for general security-concept questions). Never invents a risk
    verdict, a finding, or an app's minSdkVersion - every factual claim
    traces to database.get_app_assessment[_by_id]() or a fixed CWE
    definition.
    """
    question = _strip_legacy_context_prefix(msg)
    intent = _classify_intent(question)

    if intent == "explain_cwe_89":
        return CWE_89_EXPLANATION
    if intent == "explain_cwe_295":
        return CWE_295_EXPLANATION

    # App-context-dependent intents need a real, resolved assessment first.
    if intent in ("why_risky", "what_to_do", "explain_recommendation", "compatibility") and app_id is not None:
        assessment = database.get_app_assessment_by_id(app_id)
        if assessment is None:
            return "I don't have a verified security assessment for the selected app yet. Upload its APK to get a real analysis."
        if intent == "why_risky":
            return answer_why_risky(assessment)
        if intent == "what_to_do":
            return answer_what_to_do(assessment)
        if intent == "explain_recommendation":
            return answer_recommendation_explanation(assessment)
        if intent == "compatibility":
            return answer_compatibility_question(assessment, user_android_version)

    if intent == "compatibility" and app_id is None:
        return "Tell me which app you mean (open this chat from that app's details screen, or ask e.g. 'Is TikTok safe?' first) and I can check its Android version requirement against your device."

    # Fallback: existing app-name-lookup behavior, unchanged.
    found_app = _extract_app_name(question)

    if not found_app:
        return GREETING

    analysis = analyze_user_query(found_app, user_ram_mb, user_android_version)

    if not analysis["assessed"]:
        return (
            f"I don't have a verified security assessment for '{found_app}' yet. 🔍\n\n"
            "No one has analysed this app's APK on DualVulnDroid so far. "
            "Upload its APK from the Home screen to get a real assessment."
        )

    if analysis['risk_level'] == 'high':
        response = f"I've reviewed the most recent analysed version of '{found_app}'. 🚨 It was flagged HIGH RISK.\n\n"
    elif analysis['risk_level'] == 'medium':
        response = f"I've reviewed the most recent analysed version of '{found_app}'. ⚠️ It was flagged MEDIUM RISK.\n\n"
    else:
        response = f"I've reviewed the most recent analysed version of '{found_app}'. ✅ No detected vulnerability in that version.\n\n"

    response += f"Security: {analysis['recommendation']}\n\n"

    if analysis['details']:
        response += f"Findings: {', '.join(analysis['details'])}\n\n"

    if analysis['alternatives']:
        alts = ", ".join(a["app_name"] for a in analysis['alternatives'])
        response += f"Apps in the same category with better analysed scores: {alts}.\n\n"

    response += f"(Based on {analysis['scan_count']} scan(s), most recent: {analysis['last_scanned_at']}.)"

    return response
